using System.Windows;using LabMaster.Services;namespace LabMaster;public partial class AddAnalyzerWindow:Window{readonly AnalyzerService service=new();readonly DepartmentService departments=new();public AddAnalyzerWindow(){InitializeComponent();Loaded+=async(_,_)=>DepartmentBox.ItemsSource=await departments.GetAsync();}async void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(CodeBox.Text)||string.IsNullOrWhiteSpace(NameBox.Text)){MessageBox.Show("Analyzer code and name are required.");return;}try{var d=DepartmentBox.SelectedItem as DepartmentRow;await service.AddAsync(CodeBox.Text,NameBox.Text,d?.DepartmentId,string.IsNullOrWhiteSpace(ManufacturerBox.Text)?null:ManufacturerBox.Text.Trim(),string.IsNullOrWhiteSpace(ModelBox.Text)?null:ModelBox.Text.Trim(),string.IsNullOrWhiteSpace(SerialBox.Text)?null:SerialBox.Text.Trim(),string.IsNullOrWhiteSpace(ConnectionBox.Text)?null:ConnectionBox.Text.Trim(),LastCalibrationBox.SelectedDate,NextCalibrationBox.SelectedDate,string.IsNullOrWhiteSpace(NotesBox.Text)?null:NotesBox.Text.Trim());DialogResult=true;}catch(Exception ex){MessageBox.Show(ex.Message,"Lab Master",MessageBoxButton.OK,MessageBoxImage.Error);}}void Cancel_Click(object s,RoutedEventArgs e)=>DialogResult=false;}